Input: {"question": "When did Shoreditch station open?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0472-32fcf2abe99e:d00", "start": 0, "end": 151, "text": "Shoreditch railway station Shoreditch was a railway station on the North London Railway (NLR) in Shoreditch, London, that was in use from 1865 to 1940."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0472-32fcf2abe99e:d00", "start": 152, "end": 226, "text": "It was situated on a viaduct between Haggerston and Broad Street stations."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0472-32fcf2abe99e:d00", "start": 227, "end": 369, "text": "It should not be confused with Shoreditch Underground station (1869-2006) on the London Underground, situated about half a mile further south."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0472-32fcf2abe99e:d00", "start": 370, "end": 509, "text": "It was also not the first main line railway station to possess the Shoreditch name; Bishopsgate (1840-1875) was originally given that name."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0472-32fcf2abe99e:d00", "start": 510, "end": 636, "text": "Opened on 1 November 1865, Shoreditch station was served by local services from Broad Street towards Poplar (East India Road)."}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0472-32fcf2abe99e:d01", "start": 0, "end": 122, "text": "Shoreditch tube station Shoreditch was a London Underground station in the London Borough of Tower Hamlets in east London."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0472-32fcf2abe99e:d01", "start": 123, "end": 310, "text": "Originally opened by the East London Railway in 1876, the station was permanently closed in 2006 being replaced directly to the west of the site by Shoreditch High Street station in 2010."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0472-32fcf2abe99e:d01", "start": 311, "end": 419, "text": "The new Shoreditch High Street replacement station switched networks and is a part of the London Overground."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0472-32fcf2abe99e:d01", "start": 420, "end": 590, "text": "The station should not be confused with the Shoreditch main line station, some distance further north on the North London Railway, that opened in 1865 and closed in 1940."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0472-32fcf2abe99e:d01", "start": 591, "end": 606, "text": "The station was"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0472-32fcf2abe99e:d02", "start": 0, "end": 59, "text": "with a further spur being added to New Cross Gate in 1876 ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0472-32fcf2abe99e:d02", "start": 60, "end": 157, "text": "In 1879 the City Lines Act authorized a connection between the Inner Circle and the East London ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0472-32fcf2abe99e:d02", "start": 158, "end": 291, "text": "This was to be owned jointly by the Metropolitan and the District and joined the East London Line just south of Whitechapel station ."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0472-32fcf2abe99e:d02", "start": 292, "end": 397, "text": "With the withdrawal of the SER service the GER started running trains onto the East London Line in 1886 ."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0472-32fcf2abe99e:d02", "start": 398, "end": 485, "text": "After the Circle Line was electrified Metropolitan and District trains were withdrawn ."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0472-32fcf2abe99e:d02", "start": 486, "end": 562, "text": "In 1913 fourth rail electrification of the East London was completed between"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0472-32fcf2abe99e:d03", "start": 0, "end": 101, "text": "the main line railway station of the same name that closed in 1940 , see Shoreditch railway station ."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0472-32fcf2abe99e:d03", "start": 102, "end": 214, "text": "For the nearby replacement Overground station that opened in 2010 , see Shoreditch High Street railway station ."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0472-32fcf2abe99e:d03", "start": 215, "end": 611, "text": "Shoreditch Shoreditch Location of Shoreditch in Central London Location Pedley Street [ 1 ] Local authority London Borough of Tower Hamlets Owner London Underground Number of platforms 1 ( originally 2 ) Key dates 19 April 1876 ( 1876-04-19 ) Opened 9 June 2006 ( 2006-06-09 ) Closed Replaced by Shoreditch High Street Other information Coordinates 51°31′22″N 0°04′15″W ﻿ / ﻿ 51.52278°N 0.07083°W"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0472-32fcf2abe99e:d04", "start": 0, "end": 149, "text": "Shoreditch High Street railway station Shoreditch High Street is a London Overground station on Bethnal Green Road in Shoreditch, in London, England."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0472-32fcf2abe99e:d04", "start": 150, "end": 284, "text": "It is served by the East London Line between and with services running either to , or , , West Croydon, , and is in Travelcard Zone 1."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0472-32fcf2abe99e:d04", "start": 285, "end": 431, "text": "The station officially opened to the public on 27 April 2010 and replaced nearby tube station , which was directly to the east and closed in 2006."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0472-32fcf2abe99e:d04", "start": 432, "end": 524, "text": "On the 1994 \"planning\" version of the underground map, the station was called 'Bishopsgate'."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0472-32fcf2abe99e:d04", "start": 525, "end": 572, "text": "In May 2008 Abdal Ullah, a Tower Hamlets London"}}, "candidates": [{"candidate_id": "C0", "answer": "1 November 1865", "card_ids": ["ramdocs-0472-32fcf2abe99e:d00:c0"]}, {"candidate_id": "C1", "answer": "1876", "card_ids": ["ramdocs-0472-32fcf2abe99e:d01:c0"]}, {"candidate_id": "C2", "answer": "19 April 1876", "card_ids": ["ramdocs-0472-32fcf2abe99e:d03:c0"]}, {"candidate_id": "C3", "answer": "27 April 2010", "card_ids": ["ramdocs-0472-32fcf2abe99e:d04:c0"]}], "original_cards": [{"doc_id": "ramdocs-0472-32fcf2abe99e:d00", "card_id": "ramdocs-0472-32fcf2abe99e:d00:c0", "entity": "Shoreditch station", "scope": "Opening date", "claim": "Shoreditch station opened on 1 November 1865.", "answer": "1 November 1865", "quote": "Opened on 1 November 1865, Shoreditch station was served by local services from Broad Street towards Poplar (East India Road).", "original_document_number": 1}, {"doc_id": "ramdocs-0472-32fcf2abe99e:d01", "card_id": "ramdocs-0472-32fcf2abe99e:d01:c0", "entity": "Shoreditch tube station", "scope": "Opening date", "claim": "Shoreditch tube station was originally opened by the East London Railway in 1876.", "answer": "1876", "quote": "Originally opened by the East London Railway in 1876, the station was permanently closed in 2006 being replaced directly to the west of the site by Shoreditch High Street station in 2010.", "original_document_number": 2}, {"doc_id": "ramdocs-0472-32fcf2abe99e:d03", "card_id": "ramdocs-0472-32fcf2abe99e:d03:c0", "entity": "Shoreditch station", "scope": "Opened date", "claim": "Shoreditch station opened on 19 April 1876.", "answer": "19 April 1876", "quote": "Shoreditch Shoreditch Location of Shoreditch in Central London Location Pedley Street [ 1 ] Local authority London Borough of Tower Hamlets Owner London Underground Number of platforms 1 ( originally 2 ) Key dates 19 April 1876 ( 1876-04-19 ) Opened 9 June 2006 ( 2006-06-09 ) Closed Replaced by Shoreditch High Street Other information Coordinates 51°31′22″N 0°04′15″W ﻿ / ﻿ 51.52278°N 0.07083°W", "original_document_number": 4}, {"doc_id": "ramdocs-0472-32fcf2abe99e:d04", "card_id": "ramdocs-0472-32fcf2abe99e:d04:c0", "entity": "Shoreditch High Street railway station", "scope": "Opening date", "claim": "The station officially opened to the public on 27 April 2010.", "ans